detection_pack.kql:
// ================================================================
// KQL — Microsoft Sentinel / Defender XDR
// APEX Advisory: Beware of fake Indeed interview apps used to install spyware
// CVE: CDB-ADVISORY-BEWARE-OF-FAKE-INDEED-INTERVIE | Class: GENERIC_CVE | APEX v184.0
// Generated: 2026-10-11
// ================================================================

let lookback = 30d;

// IOC-based hunt — network events
let apex_iocs = dynamic(["7796C6ADC5D9EC00EA41B80648329B37", "8EA8F77C03AC58ACC19C25DDC6D1CD48", "D6B7F7C2514AC5AC93C5EB93E80EF317"]);
DeviceNetworkEvents
| where Timestamp > ago(lookback)
| where RemoteUrl has_any (apex_iocs) or RemoteIP has_any (apex_iocs)
| extend Severity = "High", Rule = "APEX-CDB-ADVISORY-BEWARE-OF-FAKE-INDEED-INTERVIE-IOC"
| project Timestamp, DeviceName, RemoteUrl, RemoteIP, InitiatingProcessFileName, Severity, Rule
| order by Timestamp desc;


// Alert rule: SecurityAlert table correlation
SecurityAlert
| where TimeGenerated > ago(lookback)
| where AlertName contains "CDB-ADVISORY-BEWARE-OF-FAKE-INDEED-INTERVIE" or Description contains "CDB-ADVISORY-BEWARE-OF-FAKE-INDEED-INTERVIE"
| extend Rule = "APEX-CDB-ADVISORY-BEWARE-OF-FAKE-INDEED-INTERVIE-ALERT"
| project TimeGenerated, AlertName, AlertSeverity, Entities, Description, Rule
| order by TimeGenerated desc;

detection_pack.elastic_eql:
// Elastic EQL: Beware of fake Indeed interview apps used to install spyware | Techniques: TT1190
process where
  (process.command_line != null)

sigma.retro_hunt_query:
// RETRO-HUNT: intel--2d939929cf173eda50fff3ac | Techniques: T1190 | Lookback: 90d
// Generated by APEX Detection Validation Engine v162.0.0
let lookback = 90d;
let indicators = dynamic(["<indicator>"]);
union DeviceProcessEvents, DeviceNetworkEvents, DeviceFileEvents
| where TimeGenerated > ago(lookback)
| where ProcessCommandLine has_any (indicators)
    or RemoteUrl has_any (indicators)
    or FileName has_any (indicators)
| summarize HuntHits=count(), FirstSeen=min(TimeGenerated),
    LastSeen=max(TimeGenerated), Devices=dcount(DeviceName)
    by DeviceName, ProcessCommandLine, ThreatScore=80
| where HuntHits > 0 | order by HuntHits desc

